        private static string GetBullBullLayout(string sDesc, string slang, string GameId3rd, string bettype)
        {
            const string strBullReefKey = "GT_Hands";
            var GameDetail = sDesc.Split('*');
            var result = GetSplitValue('=', GameDetail[3]);
            var results = GetSplitValue('=', GameDetail[4]);
            var winResult = GetSplitValue('=', GameDetail[5]);

            var resultCard = result.Split(':')[0].Replace("0", "").Trim();
            var resultTitle = result.Split(':')[1].Split(';')[0].Replace("B", GTCasinoResource.Banker).Replace("P", GTCasinoResource.Player);
            var resultCards = result.Split(':')[1].Replace("B;", "").Replace("P;", "").Replace(";", ",").Replace("0", "");
            var resultName = refDataHelper.GetResourceDataByRefIdAndResourceId(strBullReefKey, GetSplitValue(';', results.Split(':')[0]).Trim(), slang, "");
            var player1Cards = result.Split(':')[2].Replace("P1;", "").Replace(";", ",").Replace("0", "").Insert(3, "<br/>");
            var player1Name = refDataHelper.GetResourceDataByRefIdAndResourceId(strBullReefKey, GetSplitValue(';', results.Split(':')[1]).Trim(), slang, "");
            var player2Cards = result.Split(':')[3].Replace("P2;", "").Replace(";", ",").Replace("0", "").Insert(3, "<br/>"); ;
            var player2Name = refDataHelper.GetResourceDataByRefIdAndResourceId(strBullReefKey, GetSplitValue(';', results.Split(':')[2]).Trim(), slang, "");
            var player3Cards = result.Split(':')[4].Replace("P3;", "").Replace(";", ",").Replace("0", "").Insert(3, "<br/>"); ;
            var player3Name = refDataHelper.GetResourceDataByRefIdAndResourceId(strBullReefKey, GetSplitValue(';', results.Split(':')[3]).Trim(), slang, "");

            var strFinalScore = new List<string>();
            var winResults = winResult.Split(';');
            for (int j = 0; j < winResults.Length; j++)
            {
                var name = refDataHelper.GetResourceDataByRefIdAndResourceId(strRefKey, winResults[j].Trim(), slang, "");
                strFinalScore.Add(name);
            }

            var strFinalLayout = GetFinalLayout(bettype);

            return String.Format(strFinalLayout,
                "Game ID : " + GameId3rd,
                GetCardImgPath(resultCard),
                $"{resultTitle}: ",
                GetCardImgPath(resultCards),
                resultName,
                $"{GTCasinoResource.Player1}: {player1Name}",
                GetCardImgPath(player1Cards),
                $"{GTCasinoResource.Player2}: {player2Name}",
                GetCardImgPath(player2Cards),
                $"{GTCasinoResource.Player3}: {player3Name}",
                GetCardImgPath(player3Cards),
                string.Join(", ", strFinalScore));
        }

        private static string GetRouletteLayout(string sDesc, string slang, string GameId3rd, string bettype)
        {
            string[] GameDetail = sDesc.Split('*');

            string strImgValue = GetSplitValue('=', GameDetail[3].ToString());
            string strImgUrl = GenImgUrl("Roulette", strImgValue);
            string strFinalScore = "";
            string[] strResult = GetSplitValue('=', GameDetail[5].ToString()).Split(';');
            for (int j = 0; j < strResult.Length; j++)
            {
                if (j == 0)
                    strFinalScore += refDataHelper.GetResourceDataByRefIdAndResourceId(strRefKey, strResult[j].ToString(), slang, "");
                else
                    strFinalScore += ", " + refDataHelper.GetResourceDataByRefIdAndResourceId(strRefKey, strResult[j].ToString(), slang, "");
            }
            string strFinalLayout = GetFinalLayout(bettype);

            return String.Format(strFinalLayout, "Game ID : " + GameId3rd, "Results", strImgUrl, strFinalScore);
        }

