        private static string GetSplitValue(char strSymbol, string strValue)
        {
            string[] strTemp = strValue.Split(strSymbol);
            return strTemp[1].ToString();
        }

        #region RenderTemplate 套用模板輸出網頁資料
        private static void RenderTemplate()
        {
            strPlayerImg = GetCardImgPath(strPlayerCardValue);
            strBankerImg = GetCardImgPath(strBankerCardValue);
        }
        #endregion

        private static string GetCardImgPath(string CardValue)
        {
            string SkinPath = (_ImgPath == "") ? @"template/public/game_result/" : _ImgPath;
            string strCardImg = "";
            string[] strCard = CardValue.Split(',');
            for (int j = 0; j < strCard.Length; j++)
            {
                if (strCard[j].Contains("<br/>"))
                {
                    strCardImg += @"<img src='" + SkinPath + "Poker/" + strCard[j].ToString().Replace("<br/>", "") + ".png' align='absmiddle' border='0' class='code' />";
                    strCardImg += "<br/>";
                }
                else
                {
                    strCardImg += @"<img src='" + SkinPath + "Poker/" + strCard[j].ToString() + ".png' align='absmiddle' border='0' class='code' />";
                }
            }

            return strCardImg;
        }

        private static string GenImgUrl(string sMode, string sResult)
        {
            string sImgUrl = "";
            string skinroot_path = (_ImgPath == "") ? @"template\public\game_result\" : _ImgPath;

            if (sMode == "Roulette")
            {
                skinroot_path += @"Roulette\";
                sImgUrl = "<img  src=\"" + skinroot_path + sResult + ".png\"  align=\"absmiddle\" border=\"0\" />";
            }
            else
            {
                skinroot_path += @"Sicbo\";
                string[] strResult = sResult.Split(';');
                string temp = "ScoreBoard_d";
                for (int j = 0; j < strResult.Length; j++)
                {
                    sImgUrl += "<img  src=\"" + skinroot_path + temp + strResult[j].ToString() + ".png\"  align=\"absmiddle\" border=\"0\" />";
                }
            }

            return sImgUrl;
        }

